import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { subscribe_unsubscribe_from_directory } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    addDeleteMember: Boolean,
    rowInfo: Object,
    actionType: String
  },
  mixins: [get_all_org_users],
  data() {
    return {
      loading: false,
      userArray: [],
      selectTeam: [],
      searchF: ""
    };
  },
  watch: {
    addDeleteMember: {
      async handler() {
        if (this.actionType == "Add") {
          this.$store.commit("Setnamesearch", "");
          await this.get_all_org_users();
          await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      // Only reset form if it exists (when actionType is 'Add')
      if (this.$refs.form) {
        this.$refs.form.reset();
      }
    },
    async delete_add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      var userId = [];
      userId.push(this.rowInfo.user_id);
      // console.log(this.entryInfo.responseObject.directory_id);
      try {
        let result = await API.graphql(graphqlOperation(subscribe_unsubscribe_from_directory, {
          input: {
            directory_id: this.$store.getters.GetFormObject.directory_id,
            user_id: this.actionType == "Add" ? this.selectTeam : userId,
            action_type: this.actionType == "Add" ? "SUBSCRIBE" : "UNSUBSCRIBE"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.subscribe_unsubscribe_from_directory);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async validation_add() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.delete_add_mutation();
      }
    },
    fetch_details() {
      var data = this.$store.getters.GetUserObj;
      var existingMembers = localStorage.getItem("directoryMembers");
      var existingData = JSON.parse(existingMembers);
      var oldArray = [];
      existingData.forEach(element => {
        oldArray.push({
          full_user_name: element.full_user_name,
          user_id: element.user_id
        });
      });
      var allusers = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          allusers.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
      let uniqueInArray1 = oldArray.filter(obj1 => !allusers.find(obj2 => obj1.full_user_name === obj2.full_user_name && obj1.user_id === obj2.user_id));
      let uniqueInArray2 = allusers.filter(obj2 => !oldArray.find(obj1 => obj1.full_user_name === obj2.full_user_name && obj1.user_id === obj2.user_id));
      let finalArray = [...uniqueInArray1, ...uniqueInArray2];
      this.userArray = finalArray;
    },
    function_check() {
      // alert(5);
    }
  }
};
